from html import escape as E
LAT=[]
def add(id,title,lead,body):LAT.append(dict(id=id,n='',eyebrow='主读 · 自由教育传统',title=title,lead=lead,body=body))
def table(headers,rows):return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+E(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def topic(title,meaning,reason,example,limit):return f'<article class="lat-topic"><h3>{title}</h3><h4>本质：这个概念在解决什么问题</h4><p>{meaning}</p><h4>逻辑：为什么它不可被其他部分替代</h4><p>{reason}</p><h4>课堂：把概念变成可观察的行动</h4><p>{example}</p><h4>辨析：在哪里容易走偏</h4><p>{limit}</p></article>'
add('sec-lat','先认准这本书，再抓住它真正的问题','《自由教育传统：基督教古典教育哲学》｜The Liberal Arts Tradition: A Philosophy of Christian Classical Education', '''<div class="callout"><b>这次主读：Kevin Clark 与 Ravi Jain</b><p>中文作者名依照片：凯文·克拉克、拉维·杰恩。英文出版记录亦见 Ravi Scott Jain。王怡、苏炳森等《基督教古典教育》是另一本中文文集，现移为书目馆中的延伸阅读，不再作为本页的原书。</p></div><h3>一句话抓住全书</h3><p class="lat-thesis">教育不仅要问“教会了什么”，还要问“学习者正在成为什么样的人”；七艺必须放在敬虔、身体、情感、智慧与神学共同构成的生活中。</p><p>这是对全书范式的简要归纳。出版社和作者课程均明确把七艺置于更大的教育结构：敬虔、体育、乐教、自由技艺、哲学、神学。它要纠正的，是把基督教古典教育压缩成语言训练或一种年龄分段公式。<a class="ref" href="https://classicalacademicpress.com/pages/the-liberal-arts-tradition-details">出版社说明 ↗</a></p><h3>本页依据和阅读边界</h3>'''+table(['层次','已经掌握','如何使用'],[
('你的四张照片','题名页；两页目录；教育之树插图。','可核实书名、作者、目录结构与图中词语。没有版权页，不能据此确认译者、出版方、翻译年或正式出版身份。'),
('作者与出版社资料','出版社范式说明；ClassicalU第2、3课讲义；已核实版本记录。','用于核对总体思想。不同版本的章目与页码不互换。'),
('本站原创解读','概念辨析、经文关联、改革宗评价、课程案例、讨论与记忆。','是围绕已知框架展开的分析，不是逐页复述；未见原文的小节不声称已经重建作者全部论证。')])+'''<h3>版本关系：避免把树上的年份当出版年</h3><p>英文早期馆藏有2013记录，出版社回溯介绍常用2014；2019有修订版，现售第三版加入实践材料。照片中的四部分与七附录提示它与修订结构有关，但没有版权页，不能确定底本。插图署名的2013是图上标注的年份，不足以断定这册中文本的出版时间。</p><p>此前书目馆将本书记为“中译未核实”。现在应更新为：<b>已见用户提供的中文文本；正式出版信息仍未核实</b>。这是证据增加后的修正，不把私人文本等同正式发行的译本。</p><h3>先理解两层“自由”</h3><p>Liberal arts在这里指传统中的自由技艺、博雅技艺，不是政治立场标签，也不是“想学什么就学什么”。自由需要能够认识、判断、表达的人；在基督教立场下，自由更不能与顺服真理分离。阅读时要同时警惕两种缩减：把学习仅当就业工具，或把博雅教育当有闲阶层的身份装饰。</p><div class="two"><article><h4>10分钟路径</h4><p>本节主旨 → 教育之树 → 两种音乐 → 神学与恩典 → 一张回忆卡。</p></article><article><h4>深读路径</h4><p>照片目录 → 四部分逐层导读 → 七附录的问题 → 实践案例 → 讨论与答案 → 原书查证。</p></article></div>''')

